using System;using System.IO;using System.Reflection;using System.Windows.Forms;using System.Diagnostics;using System.Threading;using System.Threading.Tasks;using System.Collections.Generic;
static class ReconnectIntegration {
 static void Wait(Func<bool> predicate,string message){var watch=Stopwatch.StartNew();while(!predicate()&&watch.ElapsedMilliseconds<8000){Application.DoEvents();Thread.Sleep(10);}if(!predicate())throw new Exception(message);Console.WriteLine("PASS: "+message);}
 public static void Run(MainWindow form){var flags=BindingFlags.Instance|BindingFlags.NonPublic;string directory=Path.Combine(Path.GetTempPath(),"MultiVPNConnect-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);string config=Path.Combine(directory,"test.ovpn");File.WriteAllText(config,"client\n# drop-once\n");var profile=new Profile{Name="Recovery fixture",Kind="OpenVPN",Path=config};string key=CredentialStore.Key(profile);Func<VpnSession> current=()=>typeof(MainWindow).GetField("session",flags).GetValue(form) as VpnSession;
  try{CredentialStore.Save(key,"test-user","test-password");typeof(MainWindow).GetField("profiles",flags).SetValue(form,new List<Profile>{profile});typeof(MainWindow).GetMethod("RefreshList",flags).Invoke(form,null);typeof(MainWindow).GetMethod("Connect",flags).Invoke(form,new object[]{null,EventArgs.Empty});Wait(()=>current()!=null&&current().State=="Connected","Real connect path uses saved login with the isolated VPN simulator");var first=current();Wait(()=>File.Exists(config+".dropped"),"Simulator drops the established connection");Thread.Sleep(350);var recovery=(RecoveryPolicy)typeof(MainWindow).GetField("recovery",flags).GetValue(form);recovery.Schedule(DateTime.UtcNow.AddMinutes(-1));typeof(MainWindow).GetMethod("Poll",flags).Invoke(form,new object[]{null,EventArgs.Empty});Wait(()=>current()!=null&&!Object.ReferenceEquals(first,current())&&current().State=="Connected","Automatic recovery replaces a dropped engine and reconnects through the real polling path");var stop=(Task<bool>)typeof(MainWindow).GetMethod("Stop",flags).Invoke(form,null);Wait(()=>stop.IsCompleted,"Manual disconnect completes after recovery");if(!stop.Result||current()!=null||recovery.Schedule(DateTime.UtcNow))throw new Exception("Manual disconnect did not cancel recovery");Console.WriteLine("PASS: Manual disconnect cancels recovery after an actual automatic reconnect");}
  finally{var session=current();if(session!=null){var stop=(Task<bool>)typeof(MainWindow).GetMethod("Stop",flags).Invoke(form,null);Wait(()=>stop.IsCompleted,"Recovery fixture cleanup");}CredentialStore.Forget(key);File.Delete(config);if(File.Exists(config+".dropped"))File.Delete(config+".dropped");Directory.Delete(directory);}
 }
}
